package com.luci.pianoroom;
public final class AudioHealth {
 public static int nextBuffer(int requested,double accepted,int failures){int step=failures>=4?4:2;return Math.min(120,Math.max(requested+step,(int)Math.ceil(accepted)+step));}
 public static String explain(int xruns,int conflicts,int late,float peak,float limited){StringBuilder s=new StringBuilder();if(xruns>0)s.append("A saída registrou falta de áudio. Compare os tempos de amostras/efeitos/eventos e o WAV gravado; isso não prova falta de largura de banda MIDI. ");if(conflicts>0)s.append("Houve disputa com alterações no motor; compare tocando sem mover controles. ");if(late>0)s.append("O processamento ultrapassou o prazo de alguns blocos. Use o benchmark para conferir os picos por etapa; o acúmulo de efeitos ou vozes pode ultrapassar a capacidade de tempo real. ");if(peak>1||limited>5)s.append("A mistura está exigindo proteção de volume. Compare faders/Master menores e aumente o volume físico depois. ");if(s.length()==0)s.append("Nenhum sinal recente de falta de áudio ou saturação relevante. Se ouvir estalos, capture o diagnóstico logo após a passagem; compare outro banco e o WAV gravado com a saída USB.");return s.toString();}
}
